#!/bin/sh
echo linting
exit 0

{
  "env": {
    "ACME_TOKEN": ""
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash|PowerShell",
        "hooks": [
          {
            "type": "command",
            "command": "python3",
            "args": [
              "${CLAUDE_PROJECT_DIR}/.claude/hooks/guard-path.py"
            ],
            "timeout": 10
          }
        ]
      }
    ]
  }
}

{
  "mcpServers": {
    "tracker": {
      "command": "npx",
      "args": [
        "acme-tracker"
      ],
      "env": {
        "ACME_ORG": "acme"
      }
    }
  }
}

{
  "mcpServers": {
    "tracker": {
      "command": "npx",
      "args": [
        "acme-tracker"
      ],
      "env": {
        "ACME_ORG": "acme"
      }
    }
  }
}

{
  "servers": {
    "tracker": {
      "command": "npx",
      "args": [
        "acme-tracker"
      ],
      "env": {
        "ACME_ORG": "acme"
      }
    }
  }
}

