#!/bin/sh
echo linting
exit 0

{
  "env": {
    "ACME_TOKEN": ""
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash|PowerShell",
        "hooks": [
          {
            "type": "command",
            "command": "python3",
            "args": [
              "${CLAUDE_PROJECT_DIR}/.claude/hooks/guard-path.py"
            ],
            "timeout": 10
          }
        ]
      }
    ]
  }
}

{
  "mcpServers": {
    "tracker": {
      "command": "npx",
      "args": [
        "acme-tracker"
      ],
      "env": {
        "ACME_ORG": "acme"
      }
    }
  }
}

{
  "name": "helper",
  "description": "Helps with tasks",
  "prompt": "Help the user with their tasks.",
  "tools": [],
  "allowedTools": [],
  "resources": [
    "file://.kiro/steering/**/*.md"
  ],
  "permissions": {
    "rules": [
      {
        "capability": "fs_read",
        "match": [
          "./**"
        ],
        "effect": "allow"
      }
    ]
  }
}

{
  "mcpServers": {
    "tracker": {
      "command": "npx",
      "args": [
        "acme-tracker"
      ],
      "env": {
        "ACME_ORG": "acme"
      }
    }
  }
}

{
  "mcpServers": {
    "tracker": {
      "command": "npx",
      "args": [
        "acme-tracker"
      ],
      "env": {
        "ACME_ORG": "acme"
      }
    }
  }
}

